use function Phit\fit_ols;

$data = [
    'rent' =&gt; [
        1879.25, 1805.03, 2022.29, 1267.85,
        1509.24, 2240.10, 959.51, 2386.54,
    ],
    'area' =&gt; [
        74.4, 57.4, 66.4, 49.1,
        45.7, 92.4, 37.0, 93.9,
    ],
    'district' =&gt; [
        'north', 'south', 'north', 'east',
