Code
use Phiz\Plot;

use function Phit\fit_mixed_gaussian;
use function Phpolars\scan_csv;

$data = scan_csv('schools.csv')
    -&gt;select(['school', 'study_hours', 'score'])
    -&gt;collect()
    -&gt;toColumns();

// A random intercept per school, fitted by REML.
$fit = fit_mixed_gaussian(
    'score ~ study_hours + (1 | school)',
    $data,
);
$data['fitted'] = $fit['fitted'];

foreach ($fit['columns'] as $i =&gt; $name) {
    printf(
        "%-12s %7.3f (se %.3f)\n",
        $name,
        $fit['coefficients'][$i],
        $fit['std_errors'][$i],
    );
}
printf(
    "school SD %.3f, residual SD %.3f\n",
    sqrt($fit['random'][0]['covariance'][0][0]),
    $fit['sigma'],
);

// Students as points, and one fitted line per school.
$chart = Plot::of($data)
    -&gt;aes(x: 'study_hours', y: 'score')
    -&gt;point(alpha: 0.3)
    -&gt;line(
        aes: ['y' =&gt; 'fitted', 'group' =&gt; 'school'],
        alpha: 0.6,
    )
    -&gt;labs(x: 'Study hours', y: 'Test score')
    -&gt;theme(baseSize: 15)
    -&gt;size('container', 380);

file_put_contents(
    'schools.html',
    $chart-&gt;html('Scores by school'),
);

Code
use function Phit\{fit_ols, predict};

$flats = [
    'rent' =&gt; [
        1879.25, 1805.03, 2022.29, 1267.85, 1509.24,
        2240.10, 959.51, 2386.54, 1655.80, 1420.00,
    ],
    'area' =&gt; [
        74.4, 57.4, 66.4, 49.1, 45.7,
        92.4, 37.0, 93.9, 61.2, 52.3,
    ],
    'district' =&gt; [
        'north', 'south', 'north', 'east', 'south',
        'north', 'east', 'south', 'east', 'south',
    ],
];

$fit = fit_ols('rent ~ area + district', $flats);

foreach ($fit['columns'] as $i =&gt; $name) {
    printf(
        "%-14s %8.2f  95%% CI [%8.2f, %8.2f]\n",
        $name,
        $fit['coefficients'][$i],
        ...$fit['conf_int'][$i],
    );
}
printf(
    "R-squared %.3f, residual SD %.2f\n\n",
    $fit['r_squared'],
    $fit['sigma'],
);

$new = [
    'area' =&gt; [50.0, 80.0],
    'district' =&gt; ['east', 'north'],
];
$p = predict($fit, $new, interval: 'prediction');

foreach ($p['fit'] as $i =&gt; $rent) {
    printf(
        "%.0f m2, %-5s %8.2f  95%% PI [%7.2f, %7.2f]\n",
        $new['area'][$i],
        $new['district'][$i],
        $rent,
        $p['lower'][$i],
        $p['upper'][$i],
    );
}

